// Generated by `cargo xtask add-card`.
// Round-trip regression test for the generated test suite.
//
// Card           : Time Vault
// Set            : lea
// Collector #    : 274

#[test]
fn round_trip() {
    let text = "This artifact enters tapped.\nThis artifact doesn't untap during your untap step.\nIf you would begin your turn while this artifact is tapped, you may skip that turn instead. If you do, untap this artifact.\n{T}: Take an extra turn after this one.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    assert_eq!(
        reprinted, text,
        "unparse must preserve the normalized oracle text"
    );
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
